"""The Passport Page of a Country That Isn't There.

Writes one image, /output/entry.png: an open passport spread for the
invented Republic of Veskara (North Atlantic island nation, capital
Skardvik). Data page with photorealistic portrait and ICAO 9303 MRZ,
arrival/departure stamps from Iceland, Norway and the Faroe Islands in
one coherent travel history (all after the 14 MAR 2023 issue date), a UK
visit visa, a tide-fee stamp and a tide-permit endorsement that reveal
what kind of place Veskara is.

The artwork was composed in the build session (photorealistic passport
portrait generated in-session, layout/typesetting/stamps drawn
programmatically with exact dates and a computed MRZ) and is embedded
here as base64 so the program is fully deterministic and needs no
network: it decodes the bytes and writes them unchanged.
"""

