# sha256 of the decoded PNG, checked on every run.
EXPECTED_SHA256 = "7ca2c2565e72471acd878d304e5f6c2dc90591768796077ae5a40cb715c0010a"


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    out_path = os.path.join(out_dir, "entry.png")
    data = base64.b64decode(ENTRY_PNG_B64)
    if hashlib.sha256(data).hexdigest() != EXPECTED_SHA256:
        print("entry.png payload failed its integrity check", file=sys.stderr)
        return 1
    os.makedirs(out_dir, exist_ok=True)
    with open(out_path, "wb") as f:
        f.write(data)
    print(f"wrote {out_path}: {len(data)} bytes, sha256={EXPECTED_SHA256}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
